package com.aoo.bcg.common.cache;
import java.time.Duration;
/** Converts Redis PTTL semantics while preventing migration from extending data lifetime. */
public final class RemainingTtlPolicy{private final Duration persistentKeyCap;public RemainingTtlPolicy(Duration persistentKeyCap){if(persistentKeyCap==null||persistentKeyCap.isNegative()||persistentKeyCap.isZero())throw new IllegalArgumentException("persistent key cap required");this.persistentKeyCap=persistentKeyCap;}public Duration fromPttlMillis(long pttlMillis){if(pttlMillis==-2)throw new IllegalStateException("source key missing");if(pttlMillis==-1)return persistentKeyCap;if(pttlMillis<=0)throw new IllegalStateException("source key expired");return Duration.ofMillis(pttlMillis);}public Duration bounded(Duration remaining,Duration migrationMaximum){if(remaining.isNegative()||remaining.isZero()||migrationMaximum.isNegative()||migrationMaximum.isZero())throw new IllegalArgumentException("invalid ttl");return remaining.compareTo(migrationMaximum)<=0?remaining:migrationMaximum;}}
